// ─── Blob mascot (SVG drawn inline, no external deps) ─────────────────────────
// Avatar ID → asset key mapping
const AVATAR_IMG = {
  sunny:"avatar_sunny", fiery:"avatar_fiery", breezy:"avatar_breezy",
  rosy:"avatar_rosy", leafy:"avatar_leafy", grape:"avatar_grape",
  minty:"avatar_minty", peachy:"avatar_peachy", stormy:"avatar_stormy",
  cloudy:"avatar_cloudy",
};
function useIsMobile() {
  const [isMobile, setIsMobile] = useState(()=>window.innerWidth<=768);
  useEffect(()=>{
    const handler = ()=>setIsMobile(window.innerWidth<=768);
    window.addEventListener("resize",handler);
    return ()=>window.removeEventListener("resize",handler);
  },[]);
  return isMobile;
}

function Blob({ size=120, mood="happy", color=C.yellow, style:s={}, avatarId=null }) {
  // If we have a specific avatarId, use the custom image
  const imgKey = avatarId && AVATAR_IMG[avatarId];
  const src = imgKey && ASSETS[imgKey];
  if(src) return (
    <img src={src} width={size} height={size}
      style={{ display:"block", objectFit:"contain", ...s }} alt={avatarId}/>
  );
  // Fallback: coloured circle (for cases where no avatarId known)
  return (
    <div style={{ width:size, height:size, borderRadius:"50%",
      background:color, border:`3px solid ${C.black}`,
      display:"flex", alignItems:"center", justifyContent:"center",
      fontSize:Math.round(size*0.4)+"px", ...s }}>
      😊
    </div>
  );
}

// ─── Press-effect pill button ─────────────────────────────────────────────────
function PillBtn({ children, onClick, color=C.yellow, textColor=C.black,
                   small=false, style:s={}, disabled=false }) {
  const [pressed, setPressed] = useState(false);
  return (
    <button
      onClick={onClick} disabled={disabled}
      onMouseDown={()=>setPressed(true)}
      onMouseUp={()=>setPressed(false)}
      onMouseLeave={()=>setPressed(false)}
      style={{
        background:    disabled ? "#ccc" : color,
        color:         disabled ? "#888" : textColor,
        border:        `3px solid ${C.black}`,
        borderRadius:  "999px",
        padding:       small ? "8px 20px" : "13px 30px",
        fontSize:      small ? "13px" : "15px",
        fontWeight:    900,
        fontFamily:    "'Nunito',sans-serif",
        cursor:        disabled ? "not-allowed" : "pointer",
        boxShadow:     pressed ? "none" : `4px 4px 0 ${C.black}`,
        transform:     pressed ? "translate(4px,4px)" : "none",
        transition:    "box-shadow .08s,transform .08s",
        display:       "inline-flex",
        alignItems:    "center",
        gap:           "6px",
        whiteSpace:    "nowrap",
        letterSpacing: ".2px",
        ...s
      }}>
      {children}
    </button>
  );
}

// ─── Card ─────────────────────────────────────────────────────────────────────
