// Helper: render place icon
function PlaceIcon({ iconId, size=20, style={} }) {
  const ic = PLACE_ICONS.find(x=>x.id===(iconId||"pin"));
  return ic
    ? <img src={ic.img} width={size} height={size} style={{objectFit:"contain",...style}} alt={ic.label}/>
    : <span style={{fontSize:size+"px"}}>📍</span>;
}

