// ─── Utility ──────────────────────────────────────────────────────────────────
function uid() { return Math.random().toString(36).slice(2,9); }
function formatDate(d) {
  if(!d) return "";
  return new Date(d).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});
}
function tripDays(trip) {
  if(trip.startDate&&trip.endDate) {
    return Math.max(1,Math.round((new Date(trip.endDate)-new Date(trip.startDate))/86400000)+1);
  }
  return trip.numDays||1;
}
function generateItinerary(locations, days) {
  const buckets = Array.from({length:days}, (_,i) => ({day:i+1, places:[]}));
  // Group by area first
  const areaMap = {};
  locations.forEach(loc => {
    const key = loc.area || "__none__";
    if(!areaMap[key]) areaMap[key] = [];
    areaMap[key].push(loc);
  });
  const areaGroups = Object.values(areaMap);
  // If more areas than days, merge smallest adjacent pairs
  while(areaGroups.length > days && areaGroups.length > 1) {
    // find smallest pair to merge
    let minIdx = 0;
    let minLen = areaGroups[0].length + areaGroups[1].length;
    for(let i=1;i<areaGroups.length-1;i++){
      const len = areaGroups[i].length + areaGroups[i+1].length;
      if(len < minLen){ minLen=len; minIdx=i; }
    }
    areaGroups.splice(minIdx, 2, [...areaGroups[minIdx], ...areaGroups[minIdx+1]]);
  }
  // Distribute groups across days
  areaGroups.forEach((group, i) => {
    const dayIdx = i % days;
    buckets[dayIdx].places.push(...group);
  });
  return buckets;
}

